import{_ as o,o as u,c as q,ai as e}from"./chunks/framework.scx6l_IK.js";const i=JSON.parse('{"title":"金刚经3分-攀缘与随缘","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经3分-攀缘与随缘.md","filePath":"60-原文段落/金刚经3分-攀缘与随缘.md","lastUpdated":1778155802000}'),a={name:"60-原文段落/金刚经3分-攀缘与随缘.md"};function r(_,t,s,n,p,c){return u(),q("div",null,[...t[0]||(t[0]=[e('<h1 id="金刚经3分-攀缘与随缘" tabindex="-1">金刚经3分-攀缘与随缘 <a class="header-anchor" href="#金刚经3分-攀缘与随缘" aria-label="Permalink to &quot;金刚经3分-攀缘与随缘&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/3了空居士讲《金刚经》-第三分大乘正宗分20160916">3了空居士讲《金刚经》-第三分大乘正宗分20160916</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【答疑】</strong></p><p>**1.问：**请教师父什么是攀缘心？</p><p><strong>了空居士：</strong>&quot;攀缘&quot;，我们说&quot;攀缘&quot;这个词吧就有两块组成，一个是&quot;攀&quot;，一个是&quot;缘&quot;。&quot;缘&quot;就是一切原因，一切外在的条件，当然包括内心的一些想法都叫做&quot;缘&quot;。&quot;攀缘&quot;，就是说你特别地去执着了某一些事情，某一些现象。&quot;攀缘&quot;相对的就是&quot;随缘&quot;。不过很多修行人都将&quot;随缘&quot;理解成&quot;随便&quot;了。他们就说&quot;你这个事情这么做好不好？&quot;&quot;随缘吧&quot;，其实就是随便，变成随便了。&quot;随缘&quot;和&quot;随便&quot;是两码事。&quot;随缘&quot;是按照客观因素、客观条件去做最合理的方案。&quot;随便&quot;就是有点不负责任了，&quot;怎么就怎么啦，没所谓啦&quot;。这&quot;攀缘&quot;就反过来，他就不按具体的状况，一厢情愿的主观地去追求。</p>',6)])])}const l=o(a,[["render",r]]);export{i as __pageData,l as default};
